CREATE OR REPLACE FUNCTION private.can_access_communication_group(p_group_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_company_id uuid;
  v_group_type text;
  v_role text;
  v_participants_only boolean;
begin
  if v_user_id is null or p_group_id is null then return false; end if;

  select cg.company_id,cg.group_type,cg.participants_only
  into v_company_id,v_group_type,v_participants_only
  from public.communication_groups cg
  where cg.id=p_group_id;

  if v_company_id is null then return false; end if;

  if v_group_type='direct'
     or (v_group_type='company' and v_participants_only) then
    return exists(
      select 1
      from public.communication_group_members cgm
      where cgm.group_id=p_group_id
        and cgm.user_id=v_user_id
    );
  end if;

  select cm.role::text into v_role
  from public.company_members cm
  where cm.company_id=v_company_id and cm.user_id=v_user_id
  limit 1;

  if v_role is null then return false; end if;

  if v_group_type='site' and v_role in ('owner','admin','manager') then
    return true;
  end if;

  if v_group_type='partner' then
    if v_role in ('owner','admin') then return true; end if;
    return exists(
      select 1
      from public.member_feature_permissions mfp
      where mfp.company_id=v_company_id
        and mfp.user_id=v_user_id
        and mfp.can_manage_partner_chat=true
    );
  end if;

  return v_group_type='company';
end
$function$

CREATE OR REPLACE FUNCTION private.invite_friend_to_chat_group(p_group_id uuid, p_friend_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_company uuid;
  v_invite uuid;
  v_group_name text;
  v_sender_name text;
begin
  if v_user is null then raise exception 'ログインが必要です'; end if;
  if p_group_id is null or p_friend_user_id is null then raise exception '招待先を確認してください'; end if;
  if p_friend_user_id = v_user then raise exception '自分自身は招待できません'; end if;

  select cg.company_id,cg.name into v_company,v_group_name
  from public.communication_groups cg
  where cg.id=p_group_id
    and cg.participants_only=true
    and exists (
      select 1 from public.communication_group_members gm
      where gm.group_id=cg.id and gm.user_id=v_user
    );
  if v_company is null then raise exception 'このグループへ招待できません'; end if;

  if not exists (
    select 1 from private.sko_friends f
    where (f.user_a=v_user and f.user_b=p_friend_user_id)
       or (f.user_b=v_user and f.user_a=p_friend_user_id)
  ) then
    raise exception '友達だけを招待できます';
  end if;

  if exists (
    select 1 from public.communication_group_members gm
    where gm.group_id=p_group_id and gm.user_id=p_friend_user_id
  ) then
    raise exception 'すでに参加しています';
  end if;

  update private.chat_group_invites
  set status='cancelled', responded_at=now()
  where group_id=p_group_id and invitee_user_id=p_friend_user_id and status='pending';

  insert into private.chat_group_invites(
    group_id,company_id,inviter_user_id,invitee_user_id
  ) values (
    p_group_id,v_company,v_user,p_friend_user_id
  )
  returning id into v_invite;

  select coalesce(nullif(up.display_name,''),'SKOユーザー') into v_sender_name
  from public.user_profiles up where up.user_id=v_user;

  insert into public.app_notifications(
    company_id,recipient_user_id,kind,title,body,action_key,action_id
  ) values (
    v_company,p_friend_user_id,'chat_group_invite','グループチャット招待',
    coalesce(v_sender_name,'SKOユーザー') || 'さんから「' || coalesce(v_group_name,'グループ') || '」へ招待されました',
    'chat_group_invite',v_invite
  );

  return v_invite;
end
$function$

CREATE OR REPLACE FUNCTION private.leave_custom_chat_group(p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_remaining integer;
begin
  if v_user is null then raise exception 'ログインが必要です'; end if;
  if not exists(
    select 1 from public.communication_groups g
    join public.communication_group_members gm on gm.group_id=g.id
    where g.id=p_group_id and g.participants_only=true and gm.user_id=v_user
  ) then raise exception '参加中のグループではありません'; end if;

  delete from public.communication_group_members
  where group_id=p_group_id and user_id=v_user;

  select count(*) into v_remaining
  from public.communication_group_members
  where group_id=p_group_id;

  if v_remaining=0 then
    delete from public.communication_groups where id=p_group_id;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION private.remove_custom_chat_group_member(p_group_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then raise exception 'ログインが必要です'; end if;
  if p_group_id is null or p_user_id is null then
    raise exception '対象メンバーを確認してください';
  end if;
  if p_user_id=v_user then
    raise exception '自分の脱退は脱退ボタンを使用してください';
  end if;

  if not exists(
    select 1
    from public.communication_groups g
    join public.communication_group_members me
      on me.group_id=g.id and me.user_id=v_user
    where g.id=p_group_id
      and g.participants_only=true
  ) then
    raise exception 'このグループのメンバーではありません';
  end if;

  if not exists(
    select 1
    from public.communication_group_members target
    where target.group_id=p_group_id
      and target.user_id=p_user_id
  ) then
    raise exception '対象メンバーが見つかりません';
  end if;

  delete from public.communication_group_members
  where group_id=p_group_id
    and user_id=p_user_id;
end
$function$

CREATE OR REPLACE FUNCTION private.respond_chat_group_invite(p_invite_id uuid, p_accept boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_invite private.chat_group_invites%rowtype;
begin
  if v_user is null then raise exception 'ログインが必要です'; end if;

  select * into v_invite
  from private.chat_group_invites
  where id=p_invite_id and invitee_user_id=v_user and status='pending'
  for update;
  if v_invite.id is null then raise exception '招待が見つかりません'; end if;

  if p_accept then
    insert into public.communication_group_members(group_id,company_id,user_id)
    values(v_invite.group_id,v_invite.company_id,v_user)
    on conflict do nothing;
    update private.chat_group_invites
    set status='accepted',responded_at=now()
    where id=p_invite_id;
  else
    update private.chat_group_invites
    set status='declined',responded_at=now()
    where id=p_invite_id;
  end if;

  return v_invite.group_id;
end
$function$
